-- =====================================================================
-- V2: Authentication schema (Phase 1)
--
-- users           identity + credentials + lockout state
-- refresh_tokens  hashed, rotating, revocable refresh tokens grouped in families
-- account_tokens  hashed one-time tokens: email verification and password reset
--
-- Primary keys are UUID v7 generated by the application (ADR-005), so no DB defaults.
-- All timestamps are TIMESTAMPTZ and written in UTC.
-- updated_at is maintained by the application (JPA), not by triggers,
-- so all write logic lives in one place.
-- =====================================================================

-- ---------------------------------------------------------------------
-- users
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id                  UUID         NOT NULL,
    email               VARCHAR(254) NOT NULL,
    password_hash       VARCHAR(255) NOT NULL,
    status              VARCHAR(32)  NOT NULL,
    email_verified_at   TIMESTAMPTZ,
    failed_login_count  INTEGER      NOT NULL DEFAULT 0,
    locked_until        TIMESTAMPTZ,
    last_login_at       TIMESTAMPTZ,
    password_changed_at TIMESTAMPTZ  NOT NULL,
    version             BIGINT       NOT NULL DEFAULT 0,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT pk_users PRIMARY KEY (id),
    -- The application stores emails trimmed and lower-cased, so a plain unique
    -- constraint is case-insensitive in practice. The CHECK guarantees it.
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_email_normalized CHECK (email = lower(btrim(email))),
    CONSTRAINT ck_users_status CHECK (status IN ('PENDING_VERIFICATION', 'ACTIVE', 'DEACTIVATED')),
    CONSTRAINT ck_users_failed_login_count CHECK (failed_login_count >= 0),
    CONSTRAINT ck_users_active_requires_verified CHECK (status <> 'ACTIVE' OR email_verified_at IS NOT NULL)
);

COMMENT ON TABLE  users                     IS 'Identity and credentials. Owned by the auth module.';
COMMENT ON COLUMN users.password_hash       IS 'Encoded hash with algorithm prefix, e.g. {argon2}$argon2id$...';
COMMENT ON COLUMN users.locked_until        IS 'Temporary lockout after repeated failed logins; NULL = not locked';
COMMENT ON COLUMN users.version             IS 'Optimistic locking counter (JPA @Version)';

-- ---------------------------------------------------------------------
-- refresh_tokens
-- ---------------------------------------------------------------------
CREATE TABLE refresh_tokens (
    id             UUID         NOT NULL,
    user_id        UUID         NOT NULL,
    family_id      UUID         NOT NULL,
    token_hash     VARCHAR(64)  NOT NULL,
    issued_at      TIMESTAMPTZ  NOT NULL,
    expires_at     TIMESTAMPTZ  NOT NULL,
    revoked_at     TIMESTAMPTZ,
    revoke_reason  VARCHAR(32),
    replaced_by_id UUID,
    created_ip     VARCHAR(45),
    user_agent     VARCHAR(255),

    CONSTRAINT pk_refresh_tokens PRIMARY KEY (id),
    CONSTRAINT fk_refresh_tokens_user
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT fk_refresh_tokens_replaced_by
        FOREIGN KEY (replaced_by_id) REFERENCES refresh_tokens (id) ON DELETE SET NULL,
    CONSTRAINT uk_refresh_tokens_token_hash UNIQUE (token_hash),
    CONSTRAINT ck_refresh_tokens_hash_format CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_refresh_tokens_expiry CHECK (expires_at > issued_at),
    CONSTRAINT ck_refresh_tokens_revoke_reason CHECK (revoke_reason IN (
        'ROTATED', 'LOGOUT', 'LOGOUT_ALL', 'REUSE_DETECTED',
        'PASSWORD_CHANGED', 'PASSWORD_RESET', 'ACCOUNT_DEACTIVATED')),
    CONSTRAINT ck_refresh_tokens_revocation_consistent CHECK ((revoked_at IS NULL) = (revoke_reason IS NULL))
);

-- Logout-all and ON DELETE CASCADE look up tokens by user.
CREATE INDEX idx_refresh_tokens_user_id    ON refresh_tokens (user_id);
-- Reuse detection revokes a whole family at once.
CREATE INDEX idx_refresh_tokens_family_id  ON refresh_tokens (family_id);
-- The cleanup job (Phase 12) deletes expired rows in ranges.
CREATE INDEX idx_refresh_tokens_expires_at ON refresh_tokens (expires_at);

COMMENT ON TABLE  refresh_tokens            IS 'Refresh tokens. Only SHA-256 hashes are stored, never raw tokens.';
COMMENT ON COLUMN refresh_tokens.family_id  IS 'All tokens descending from one login share a family; reuse revokes the family';

-- ---------------------------------------------------------------------
-- account_tokens
-- ---------------------------------------------------------------------
CREATE TABLE account_tokens (
    id          UUID        NOT NULL,
    user_id     UUID        NOT NULL,
    purpose     VARCHAR(32) NOT NULL,
    token_hash  VARCHAR(64) NOT NULL,
    expires_at  TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT pk_account_tokens PRIMARY KEY (id),
    CONSTRAINT fk_account_tokens_user
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT uk_account_tokens_token_hash UNIQUE (token_hash),
    CONSTRAINT ck_account_tokens_purpose CHECK (purpose IN ('EMAIL_VERIFICATION', 'PASSWORD_RESET')),
    CONSTRAINT ck_account_tokens_hash_format CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_account_tokens_expiry CHECK (expires_at > created_at)
);

-- Issuing a new token invalidates the user's outstanding tokens of the same purpose.
CREATE INDEX idx_account_tokens_user_purpose ON account_tokens (user_id, purpose);
CREATE INDEX idx_account_tokens_expires_at   ON account_tokens (expires_at);

COMMENT ON TABLE account_tokens IS 'One-time tokens for email verification and password reset. Hashes only.';
